use crate::licenses::{
    CrateMetadata, CrateNotice, LockPackage, bundled_licenses_text, contains_notice_for,
    format_application_license, format_license_bundle, is_full_release_bundle,
    parse_cargo_lock_packages, parse_crate_package_metadata, third_party_crate_entries,
};

#[test]
fn parse_cargo_lock_extracts_workspace_and_registry_packages() {
    let lock = r#"
# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "dualsense-updater"
version = "0.0.0"
dependencies = [
 "hidapi",
]

[[package]]
name = "hidapi"
version = "2.6.4"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "abc"

[[package]]
name = "tokio"
version = "1.54.1"
source = "registry+https://github.com/rust-lang/crates.io-index"
"#;

    let packages = parse_cargo_lock_packages(lock);
    assert_eq!(
        packages,
        vec![
            LockPackage {
                name: "dualsense-updater".to_string(),
                version: "0.0.0".to_string(),
                source: None,
            },
            LockPackage {
                name: "hidapi".to_string(),
                version: "2.6.4".to_string(),
                source: Some("registry+https://github.com/rust-lang/crates.io-index".to_string()),
            },
            LockPackage {
                name: "tokio".to_string(),
                version: "1.54.1".to_string(),
                source: Some("registry+https://github.com/rust-lang/crates.io-index".to_string()),
            },
        ]
    );
}

#[test]
fn parse_crate_package_metadata_reads_only_package_section() {
    let cargo_toml = r#"
[package]
name = "example-crate"
version = "1.2.3"
license = "MIT OR Apache-2.0" # inline comment
license-file = "LICENSE-CUSTOM"
repository = "https://example.invalid/repo"

[dependencies]
license = "SHOULD-BE-IGNORED"
repository = "https://ignored.invalid"
"#;

    let meta = parse_crate_package_metadata(cargo_toml);
    assert_eq!(
        meta,
        CrateMetadata {
            license: Some("MIT OR Apache-2.0".to_string()),
            license_file: Some("LICENSE-CUSTOM".to_string()),
            repository: Some("https://example.invalid/repo".to_string()),
        }
    );
}

#[test]
fn format_license_bundle_renders_full_and_summary_modes() {
    let notices = vec![
        CrateNotice {
            name: "alpha".to_string(),
            version: "0.1.0".to_string(),
            metadata: CrateMetadata {
                license: Some("MIT".to_string()),
                license_file: None,
                repository: Some("https://example.invalid/alpha".to_string()),
            },
            license_texts: vec![(
                "LICENSE".to_string(),
                "Permission is hereby granted, free of charge.\n".to_string(),
            )],
        },
        CrateNotice {
            name: "beta".to_string(),
            version: "2.0.0".to_string(),
            metadata: CrateMetadata::default(),
            license_texts: Vec::new(),
        },
    ];

    let summary = format_license_bundle("0.0.0", "MIT License\nRoot text", &notices, false);
    assert!(!is_full_release_bundle(&summary));
    assert!(summary.contains("DualSense Firmware Updater (v0.0.0)"));
    assert!(summary.contains("Root text"));
    assert!(summary.contains("Qt 6"));
    assert!(summary.contains("KDE Kirigami"));
    assert!(summary.contains("hidapi"));
    assert_eq!(
        third_party_crate_entries(&summary),
        vec![
            "* alpha v0.1.0 — MIT",
            "* beta v2.0.0 — See license file / unspecified",
        ]
    );
    assert!(!summary.contains("Permission is hereby granted, free of charge."));

    let full = format_license_bundle("0.0.0", "MIT License\nRoot text", &notices, true);
    assert!(is_full_release_bundle(&full));
    assert!(full.contains("--- LICENSE ---"));
    assert!(full.contains("Permission is hereby granted, free of charge."));
    assert!(full.contains("No LICENSE/COPYING/NOTICE file bundled in crate archive."));
}

#[test]
fn format_application_license_preserves_gpl_and_mit_notices() {
    let formatted = format_application_license("GPLv3+ body", "MIT body");
    assert!(formatted.contains("GPL-3.0-or-later"));
    assert!(formatted.contains("Copyright (C) 2026 Azorimor <azorimor@gmail.com>"));
    assert!(formatted.contains("Copyright (c) 2026 nchie"));
    assert!(formatted.contains("Copyright (c) 2026 Azorimor"));
    assert!(formatted.contains("--- LICENSES/GPL-3.0-or-later.txt ---\nGPLv3+ body"));
    assert!(formatted.contains("--- LICENSES/MIT.txt ---\nMIT body"));
}

#[test]
fn generated_bundled_licenses_includes_root_system_and_core_crates() {
    let text = bundled_licenses_text();
    assert!(!text.is_empty());
    assert!(contains_notice_for(text, "GPL-3.0-or-later"));
    assert!(contains_notice_for(text, "GNU GENERAL PUBLIC LICENSE"));
    assert!(contains_notice_for(text, "MIT License"));
    assert!(contains_notice_for(text, "nchie"));
    assert!(contains_notice_for(text, "Azorimor"));
    assert!(contains_notice_for(text, "Qt 6"));
    assert!(contains_notice_for(text, "KDE Kirigami"));
    assert!(contains_notice_for(text, "hidapi"));
    assert!(contains_notice_for(text, "tokio"));
    assert!(contains_notice_for(text, "cxx-qt"));
    assert!(!third_party_crate_entries(text).is_empty());
}
